def emit(locale: str) -> None:
    items = []
    seen = set()
    rows = list(ROWS)
    known = {(c, s) for c, s, _ in rows}
    for source, extra in T.items():
        key = ("HostWindow", source)
        if key not in known:
            rows.append(("HostWindow", source, extra))
    for context, source, extra in rows:
        if (context, source) in seen:
            continue
        seen.add((context, source))
        text = source if locale == "en" else extra.get(locale, source)
        items.append({"context": context, "source": source, "translation": text})
    path = ROOT / f"monasphere_{locale}.json"
    path.write_text(json.dumps({"translations": items}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    for loc in LOCALES:
        emit(loc)
